  7	int canvas_init(Canvas *c, int w, int h, void *(*alloc)(size_t)) {
  8	  c->w = w;
  9	  c->h = h;
 10	  c->px = (uint16_t *)alloc((size_t)w * (size_t)h * sizeof(uint16_t));
 11	  if (!c->px) return -1;
 12	  memset(c->px, 0, (size_t)w * (size_t)h * sizeof(uint16_t));
 13	  return 0;
 14	}
 15	
 16	void canvas_free(Canvas *c) {
 17	  free(c->px);
 18	  c->px = NULL;
 19	}
 20	
 21	uint16_t rgb565(uint8_t r, uint8_t g, uint8_t b) {
 22	  return (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
 23	}
 24	
 25	uint16_t rgb565_from16(uint16_t r, uint16_t g, uint16_t b) {
 26	  return rgb565((uint8_t)(r >> 8), (uint8_t)(g >> 8), (uint8_t)(b >> 8));
 27	}
 28	
 29	void canvas_clear(Canvas *c, uint16_t color) {
 30	  for (long i = 0, n = (long)c->w * c->h; i < n; i++) c->px[i] = color;
 31	}
 32	
 33	void canvas_point(Canvas *c, int x, int y, uint16_t color) {
 34	  if (x < 0 || y < 0 || x >= c->w || y >= c->h) return;
 35	  c->px[(size_t)y * c->w + x] = color;
 36	}
 37	
 38	static void hspan(Canvas *c, long x0, long x1, long y, uint16_t color) {
 39	  if (y < 0 || y >= c->h || x1 < 0 || x0 >= c->w) return;
 40	  if (x0 < 0) x0 = 0;
 41	  if (x1 >= c->w) x1 = c->w - 1;
 42	  uint16_t *row = c->px + (size_t)y * c->w;
 43	  for (long x = x0; x <= x1; x++) row[x] = color;
 44	}
 45	
 46	void canvas_fill_rect(Canvas *c, int x, int y, int w, int h, uint16_t color) {
 47	  if (w <= 0 || h <= 0) return;
 48	  long x1 = (long)x + w - 1, y1 = (long)y + h - 1;
 49	  long y0 = y < 0 ? 0 : y;
 50	  if (y1 >= c->h) y1 = c->h - 1;
 51	  for (long yy = y0; yy <= y1; yy++) hspan(c, x, x1, yy, color);
 52	}
 53	
 54	/* Liang-Barsky clip of the segment to [0,w-1]x[0,h-1]; false if outside. */
 55	static int clip_line(const Canvas *c, double *x0, double *y0, double *x1,
 56	                     double *y1) {
 57	  double dx = *x1 - *x0, dy = *y1 - *y0, t0 = 0, t1 = 1;
 58	  double p[4] = {-dx, dx, -dy, dy};
 59	  double q[4] = {*x0, (c->w - 1) - *x0, *y0, (c->h - 1) - *y0};
 60	  for (int i = 0; i < 4; i++) {
 61	    if (p[i] == 0) {
 62	      if (q[i] < 0) return 0;
 63	    } else {
 64	      double t = q[i] / p[i];
 65	      if (p[i] < 0) {
 66	        if (t > t1) return 0;
 67	        if (t > t0) t0 = t;
 68	      } else {
 69	        if (t < t0) return 0;
 70	        if (t < t1) t1 = t;
 71	      }
 72	    }
 73	  }
 74	  double ax = *x0, ay = *y0;
 75	  *x0 = ax + t0 * dx;
 76	  *y0 = ay + t0 * dy;
 77	  *x1 = ax + t1 * dx;
 78	  *y1 = ay + t1 * dy;
 79	  return 1;
 80	}
 81	
 82	void canvas_line(Canvas *c, int x0, int y0, int x1, int y1, uint16_t color) {
 83	  double ax = x0, ay = y0, bx = x1, by = y1;
 84	  int clipped = x0 < 0 || y0 < 0 || x0 >= c->w || y0 >= c->h || x1 < 0 ||
 85	                y1 < 0 || x1 >= c->w || y1 >= c->h;
 86	  if (clipped) {
 87	    if (!clip_line(c, &ax, &ay, &bx, &by)) return;
 88	    ax = floor(ax + 0.5);
 89	    ay = floor(ay + 0.5);
 90	    bx = floor(bx + 0.5);
 91	    by = floor(by + 0.5);
 92	  }
 93	  int ix0 = (int)ax, iy0 = (int)ay, ix1 = (int)bx, iy1 = (int)by;
 94	  int dx = abs(ix1 - ix0), sx = ix0 < ix1 ? 1 : -1;
 95	  int dy = -abs(iy1 - iy0), sy = iy0 < iy1 ? 1 : -1;
 96	  int err = dx + dy;
 97	  for (;;) {
 98	    canvas_point(c, ix0, iy0, color);
 99	    if (ix0 == ix1 && iy0 == iy1) break;
100	    int e2 = 2 * err;
101	    if (e2 >= dy) {
102	      err += dy;
103	      ix0 += sx;
104	    }
105	    if (e2 <= dx) {
106	      err += dx;
107	      iy0 += sy;
108	    }
109	  }
110	}
111	
112	void canvas_fill_ellipse(Canvas *c, int x, int y, int w, int h,
113	                         uint16_t color) {
114	  if (w <= 0 || h <= 0) return;
115	  double cx = x + (w - 1) / 2.0, cy = y + (h - 1) / 2.0;
116	  double rx = w / 2.0, ry = h / 2.0;
117	  long y0 = y < 0 ? 0 : y, y1 = (long)y + h - 1;
118	  if (y1 >= c->h) y1 = c->h - 1;
119	  for (long yy = y0; yy <= y1; yy++) {
120	    double ny = (yy - cy) / ry;
121	    double t = 1.0 - ny * ny;
122	    if (t < 0) continue;
123	    double half = rx * sqrt(t);
124	    long xa = (long)ceil(cx - half), xb = (long)floor(cx + half);
125	    if (xb < xa) continue;
126	    hspan(c, xa, xb, yy, color);
127	  }
128	}
129	
130	void canvas_fill_polygon(Canvas *c, const int *xy, int n, uint16_t color) {
131	  if (n < 3) return;
132	  long ymin = xy[1], ymax = xy[1];
133	  for (int i = 1; i < n; i++) {
134	    if (xy[2 * i + 1] < ymin) ymin = xy[2 * i + 1];
135	    if (xy[2 * i + 1] > ymax) ymax = xy[2 * i + 1];
136	  }
137	  if (ymin < 0) ymin = 0;
138	  if (ymax >= c->h) ymax = c->h - 1;
139	  for (long yy = ymin; yy <= ymax; yy++) {
140	    double xs[64];
141	    int nx = 0;
142	    double sy = yy + 0.5;
143	    for (int i = 0, j = n - 1; i < n; j = i++) {
144	      double yi = xy[2 * i + 1], yj = xy[2 * j + 1];
145	      if ((yi <= sy && yj > sy) || (yj <= sy && yi > sy)) {
146	        double t = (sy - yi) / (yj - yi);
147	        if (nx < 64) xs[nx++] = xy[2 * i] + t * (xy[2 * j] - xy[2 * i]);
148	      }
149	    }
150	    for (int a = 1; a < nx; a++)
151	      for (int b = a; b > 0 && xs[b - 1] > xs[b]; b--) {
152	        double tmp = xs[b];
153	        xs[b] = xs[b - 1];
154	        xs[b - 1] = tmp;
155	      }
156	    for (int k = 0; k + 1 < nx; k += 2)
157	      hspan(c, (long)ceil(xs[k] - 0.5), (long)ceil(xs[k + 1] - 0.5) - 1, yy,
158	            color);
159	  }
160	}

