 1	#include <M5Unified.h>
 2	#include <esp_heap_caps.h>
 3	
 4	extern "C" {
 5	#include "core/canvas.h"
 6	#include "runner/hack_runner.h"
 7	}
 8	
 9	static const int kSize = 466;
10	static const uint32_t kSliceUs = 10000;
11	static const uint32_t kStatsEveryMs = 5000;
12	
13	static Canvas canvas;
14	static HackRunner *runner;
15	static uint32_t frames;
16	static uint32_t statsAt;
17	
18	static void halt(const char *msg) {
19	  Serial.println(msg);
20	  M5.Display.fillScreen(0x000000);
21	  M5.Display.setTextColor(0xFFFFFF);
22	  M5.Display.setTextDatum(middle_center);
23	  M5.Display.drawString(msg, M5.Display.width() / 2, M5.Display.height() / 2);
24	  for (;;) delay(1000);
25	}
26	
27	static void printStats(const char *tag) {
28	  Serial.printf("%s fps=%.1f heap=%u psram=%u\n", tag,
29	                frames * 1000.0f / kStatsEveryMs, (unsigned)ESP.getFreeHeap(),
30	                (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
31	}
32	
33	void setup() {
34	  auto cfg = M5.config();
35	  M5.begin(cfg);
36	  Serial.begin(115200);
37	  M5.Display.setSwapBytes(false);
38	
39	  if (canvas_init(&canvas, kSize, kSize, ps_malloc) != 0)
40	    halt("PSRAM alloc failed");
41	  runner = runner_create(&canvas);
42	  if (!runner || runner_start(runner, 0) != 0) halt("hack start failed");
43	  printStats("boot");
44	  statsAt = millis();
45	}
46	
47	void loop() {
48	  M5.update();
49	  if (M5.BtnA.wasPressed()) runner_next(runner);
50	  if (M5.BtnB.wasPressed()) runner_prev(runner);
51	
52	  unsigned long delayUs = runner_step(runner);
53	  M5.Display.pushImage(0, 0, kSize, kSize, canvas.px);
54	  frames++;
55	
56	  uint32_t waitedUs = 0;
57	  while (waitedUs < delayUs) {
58	    uint32_t slice = delayUs - waitedUs < kSliceUs ? delayUs - waitedUs : kSliceUs;
59	    delayMicroseconds(slice);
60	    waitedUs += slice;
61	    M5.update();
62	    if (M5.BtnA.wasPressed()) runner_next(runner);
63	    if (M5.BtnB.wasPressed()) runner_prev(runner);
64	  }
65	
66	  if (millis() - statsAt >= kStatsEveryMs) {
67	    printStats("run");
68	    frames = 0;
69	    statsAt = millis();
70	  }
71	}
 1	#include "runner/hack_runner.h"
 2	
 3	#include <stdlib.h>
 4	
 5	#include "hacks/registry.h"
 6	#include "x11shim/xshim.h"
 7	
 8	#define RUNNER_WINDOW ((Window)1)
 9	
10	struct HackRunner {
11	  Canvas *canvas;
12	  Display *dpy;
13	  const HackEntry *const *hacks;
14	  int count;
15	  int index;
16	  void *closure;
17	  int running;
18	};
19	
20	HackRunner *runner_create_with(Canvas *canvas, const HackEntry *const *hacks,
21	                               int count) {
22	  HackRunner *r = (HackRunner *)calloc(1, sizeof(*r));
23	  if (!r) return NULL;
24	  r->canvas = canvas;
25	  r->dpy = xshim_open_display(canvas);
26	  r->hacks = hacks;
27	  r->count = count;
28	  if (!r->dpy) {
29	    free(r);
30	    return NULL;
31	  }
32	  return r;
33	}
34	
35	HackRunner *runner_create(Canvas *canvas) {
36	  return runner_create_with(canvas, g_hacks, g_hack_count);
37	}
38	
39	static void stop(HackRunner *r) {
40	  if (!r->running) return;
41	  r->hacks[r->index]->free(r->dpy, RUNNER_WINDOW, r->closure);
42	  r->closure = NULL;
43	  r->running = 0;
44	}
45	
46	void runner_destroy(HackRunner *r) {
47	  if (!r) return;
48	  stop(r);
49	  xshim_close_display(r->dpy);
50	  free(r);
51	}
52	
53	int runner_start(HackRunner *r, int index) {
54	  if (index < 0 || index >= r->count) return -1;
55	  stop(r);
56	  r->index = index;
57	  canvas_clear(r->canvas, 0);
58	  xshim_set_defaults(r->hacks[index]->defaults);
59	  r->closure = r->hacks[index]->init(r->dpy, RUNNER_WINDOW);
60	  r->running = 1;
61	  return 0;
62	}
63	
64	unsigned long runner_step(HackRunner *r) {
65	  if (!r->running) return RUNNER_MAX_DELAY_US;
66	  unsigned long d = r->hacks[r->index]->draw(r->dpy, RUNNER_WINDOW, r->closure);
67	  if (d < RUNNER_MIN_DELAY_US) return RUNNER_MIN_DELAY_US;
68	  if (d > RUNNER_MAX_DELAY_US) return RUNNER_MAX_DELAY_US;
69	  return d;
70	}
71	
72	int runner_next(HackRunner *r) {
73	  runner_start(r, (r->index + 1) % r->count);
74	  return r->index;
75	}
76	
77	int runner_prev(HackRunner *r) {
78	  runner_start(r, (r->index + r->count - 1) % r->count);
79	  return r->index;
80	}
81	
82	int runner_index(const HackRunner *r) { return r->index; }
