  7	
  8	static const char *const *g_defaults;
  9	
 10	void xshim_set_defaults(const char *const *defaults) { g_defaults = defaults; }
 11	
 12	/* Finds "<.|*>name:<ws>value" and returns a pointer to the value, or NULL. */
 13	static const char *lookup(const char *name) {
 14	  if (!g_defaults) return NULL;
 15	  size_t len = strlen(name);
 16	  for (const char *const *p = g_defaults; *p; p++) {
 17	    const char *s = *p;
 18	    if (*s == '.' || *s == '*') s++;
 19	    if (strncmp(s, name, len) != 0 || s[len] != ':') continue;
 20	    s += len + 1;
 21	    while (*s && isspace((unsigned char)*s)) s++;
 22	    return s;
 23	  }
 24	  return NULL;
 25	}
 26	
 27	static void warn_missing(const char *name) {
 28	  fprintf(stderr, "xshim: no default for resource '%s'\n", name);
 29	}
 30	
 31	int get_integer_resource(Display *dpy, const char *name, const char *cls) {
 32	  (void)dpy;
 33	  (void)cls;
 34	  const char *v = lookup(name);
 35	  if (!v) {
 36	    warn_missing(name);
 37	    return 0;
 38	  }
 39	  return (int)strtol(v, NULL, 0);
 40	}
 41	
 42	double get_float_resource(Display *dpy, const char *name, const char *cls) {
 43	  (void)dpy;
 44	  (void)cls;
 45	  const char *v = lookup(name);
 46	  if (!v) {
 47	    warn_missing(name);
 48	    return 0;
 49	  }
 50	  return strtod(v, NULL);
 51	}
 52	
 53	Bool get_boolean_resource(Display *dpy, const char *name, const char *cls) {
 54	  (void)dpy;
 55	  (void)cls;
 56	  const char *v = lookup(name);
 57	  if (!v) return False;
 58	  return strncasecmp(v, "true", 4) == 0 || strncasecmp(v, "on", 2) == 0 ||
 59	         strncasecmp(v, "yes", 3) == 0 || *v == '1';
 60	}
 61	
 62	char *get_string_resource(Display *dpy, const char *name, const char *cls) {
 63	  (void)dpy;
 64	  (void)cls;
 65	  const char *v = lookup(name);
 66	  return v ? strdup(v) : NULL;
 67	}
 68	
 69	unsigned long get_pixel_resource(Display *dpy, Colormap cmap, const char *name,
 70	                                 const char *cls) {
 71	  (void)dpy;
 72	  (void)cmap;
 73	  (void)cls;
 74	  const char *v = lookup(name);
 75	  if (!v) {
 76	    warn_missing(name);
 77	    return 0;
 78	  }
 79	  if (strncasecmp(v, "white", 5) == 0) return 0xFFFF;
 80	  if (strncasecmp(v, "black", 5) == 0) return 0x0000;
 81	  if (*v == '#' && strlen(v) >= 7) {
 82	    unsigned r, g, b;
 83	    if (sscanf(v + 1, "%2x%2x%2x", &r, &g, &b) == 3)
 84	      return rgb565((uint8_t)r, (uint8_t)g, (uint8_t)b);
 85	  }
 86	  fprintf(stderr, "xshim: unknown colour '%s' for '%s'\n", v, name);
 87	  return 0xFFFF;
 88	}

