 32	  (void)dpy;
 33	  (void)cls;
 34	  const char *v = lookup(name);
 35	  if (!v) {
 36	    warn_missing(name);
 37	    return 0;
 38	  }
 39	  return (int)strtol(v, NULL, 0);
 40	}
 41	
 42	double get_float_resource(Display *dpy, const char *name, const char *cls) {
 43	  (void)dpy;
 44	  (void)cls;
 45	  const char *v = lookup(name);
 46	  if (!v) {
 47	    warn_missing(name);
 48	    return 0;
 49	  }
 50	  return strtod(v, NULL);
 51	}
 52	
 53	Bool get_boolean_resource(Display *dpy, const char *name, const char *cls) {
 54	  (void)dpy;
 55	  (void)cls;
 56	  const char *v = lookup(name);
 57	  if (!v) return False;
 58	  return strncasecmp(v, "true", 4) == 0 || strncasecmp(v, "on", 2) == 0 ||
 59	         strncasecmp(v, "yes", 3) == 0 || *v == '1';
 60	}
 61	
 62	char *get_string_resource(Display *dpy, const char *name, const char *cls) {
 63	  (void)dpy;
 64	  (void)cls;
 65	  const char *v = lookup(name);
 66	  return v ? strdup(v) : NULL;
 67	}
 68	
 69	unsigned long get_pixel_resource(Display *dpy, Colormap cmap, const char *name,
 70	                                 const char *cls) {
 71	  (void)dpy;
 72	  (void)cmap;
 73	  (void)cls;
 74	  const char *v = lookup(name);
 75	  if (!v) {
 76	    warn_missing(name);
 77	    return 0;
 78	  }
 79	  if (strncasecmp(v, "white", 5) == 0) return 0xFFFF;
 80	  if (strncasecmp(v, "black", 5) == 0) return 0x0000;
 81	  if (*v == '#' && strlen(v) >= 7) {
 82	    unsigned r, g, b;
 83	    if (sscanf(v + 1, "%2x%2x%2x", &r, &g, &b) == 3)
 84	      return rgb565((uint8_t)r, (uint8_t)g, (uint8_t)b);
 85	  }
 86	  fprintf(stderr, "xshim: unknown colour '%s' for '%s'\n", v, name);
 87	  return 0xFFFF;
 88	}

